from itertools import combinations
obs=['H','V','R','Y']
true_edges=[('U','H'),('U','V'),('H','R'),('C','R'),('C','Y'),('V','Y')]
alt_edges=[('H','V'),('H','R'),('V','Y'),('C','R'),('C','Y')]
def dsep(edges,x,y,cond):
 anc=set([x,y,*cond])
 while True:
  old=anc.copy()
  anc.update(a for a,b in edges if b in anc)
  if anc==old: break
 adj={a:set() for a in anc}
 for b in anc:
  parents=[a for a,bb in edges if bb==b and a in anc]
  for a in parents:
   adj[a].add(b); adj[b].add(a)
  for a,c in combinations(parents,2):
   adj[a].add(c); adj[c].add(a)
 seen=set(cond); stack=[x]
 while stack:
  a=stack.pop()
  if a in seen: continue
  if a==y: return False
  seen.add(a); stack.extend(adj[a]-seen)
 return True
records=[]
for x,y in combinations(obs,2):
 rest=[a for a in obs if a not in [x,y]]
 for k in range(len(rest)+1):
  for z in combinations(rest,k):
   a=dsep(true_edges,x,y,z); b=dsep(alt_edges,x,y,z)
   assert a==b,(x,y,z,a,b)
   if a:records.append((x,y,z))
print('The latent-confounded generating DAG and a DAG containing H -> V -> Y have identical d-separations among the four observed nodes.')
print('Pairwise conditional independences:',records)
PY"
